1	#include "rbtree.h"
2	#include "fault_alloc.h"
3	#include <stdio.h>
4	#include <stdbool.h>
5	#include <stdlib.h>
6	#include <string.h>
7	
8	typedef enum { RED, BLACK } rb_color_t;
9	
10	struct rb_node {
11	    char           *key;
12	    void           *value;
13	    struct rb_node *parent;
14	    struct rb_node *left;
15	    struct rb_node *right;
16	    rb_color_t      color;
17	};
18	
19	struct rbtree {
20	    struct rb_node   *root;
21	    size_t            size;
22	    rb_value_free_fn  value_free;
23	};
24	
25	static bool is_red(const struct rb_node *n)  { return n != NULL && n->color == RED; }
26	static bool is_black(const struct rb_node *n) { return !is_red(n); }
27	
28	rbtree_t *rb_create(rb_value_free_fn value_free) {
29	    rbtree_t *t = rb_malloc(sizeof *t);
30	    if (t == NULL) return NULL;
31	    t->root = NULL;
32	    t->size = 0;
33	    t->value_free = value_free;
34	    return t;
35	}
36	
37	void *rb_find(const rbtree_t *t, const char *key) {
38	    struct rb_node *cur = t->root;
39	    while (cur != NULL) {
40	        int cmp = strcmp(key, cur->key);
41	        if (cmp == 0) return cur->value;
42	        cur = (cmp < 0) ? cur->left : cur->right;
43	    }
44	    return NULL;
45	}
46	
47	/* Standard BST rotation, extended to keep parent pointers and t->root
48	 * correct — rotations own root maintenance, not rb_validate. */
49	static void rotate_left(rbtree_t *t, struct rb_node *x) {
50	    struct rb_node *y = x->right;
51	    x->right = y->left;
52	    if (y->left != NULL) y->left->parent = x;
53	    y->parent = x->parent;
54	    if (x->parent == NULL)        t->root = y;
55	    else if (x == x->parent->left) x->parent->left = y;
56	    else                            x->parent->right = y;
57	    y->left = x;
58	    x->parent = y;
59	}
60	
61	static void rotate_right(rbtree_t *t, struct rb_node *x) {
62	    struct rb_node *y = x->left;
63	    x->left = y->right;
64	    if (y->right != NULL) y->right->parent = x;
65	    y->parent = x->parent;
66	    if (x->parent == NULL)         t->root = y;
67	    else if (x == x->parent->right) x->parent->right = y;
68	    else                             x->parent->left = y;
69	    y->right = x;
70	    x->parent = y;
71	}
72	
73	static void insert_fixup(rbtree_t *t, struct rb_node *z) {
74	    /* Invariant: z is red. Loop while z's parent is also red (the only
75	     * possible violation after a plain BST insert of a red node). */
76	    while (is_red(z->parent)) {
77	        struct rb_node *parent = z->parent;
78	        struct rb_node *grandparent = parent->parent;
79	        if (parent == grandparent->left) {
80	            struct rb_node *uncle = grandparent->right;
81	            if (is_red(uncle)) {
82	                parent->color = BLACK;
83	                uncle->color = BLACK;
84	                grandparent->color = RED;
85	                z = grandparent;
86	            } else {
87	                if (z == parent->right) {
88	                    z = parent;
89	                    rotate_left(t, z);
90	                    parent = z->parent;
91	                }
92	                parent->color = BLACK;
93	                grandparent->color = RED;
94	                rotate_right(t, grandparent);
95	            }
96	        } else {
97	            struct rb_node *uncle = grandparent->left;
98	            if (is_red(uncle)) {
99	                parent->color = BLACK;
100	                uncle->color = BLACK;
101	                grandparent->color = RED;
102	                z = grandparent;
103	            } else {
104	                if (z == parent->left) {
105	                    z = parent;
106	                    rotate_right(t, z);
107	                    parent = z->parent;
108	                }
109	                parent->color = BLACK;
110	                grandparent->color = RED;
111	                rotate_left(t, grandparent);
112	            }
113	        }
114	    }
115	    t->root->color = BLACK;
116	}
117	
118	int rb_insert(rbtree_t *t, const char *key, void *value) {
119	    struct rb_node *parent = NULL;
120	    struct rb_node *cur = t->root;
121	    int cmp = 0;
122	    while (cur != NULL) {
123	        cmp = strcmp(key, cur->key);
124	        if (cmp == 0) {
125	            if (t->value_free) t->value_free(cur->value);
126	            cur->value = value;
127	            return 0;
128	        }
129	        parent = cur;
130	        cur = (cmp < 0) ? cur->left : cur->right;
131	    }
132	
133	    struct rb_node *n = rb_malloc(sizeof *n);
134	    if (n == NULL) return -1;
135	
136	    size_t keylen = strlen(key) + 1;
137	    n->key = rb_malloc(keylen);
138	    if (n->key == NULL) {
139	        rb_free(n);
140	        return -1;
141	    }
142	    memcpy(n->key, key, keylen);
143	
144	    n->value = value;
145	    n->color = RED;
146	    n->left = n->right = NULL;
147	    n->parent = parent;
148	
149	    if (parent == NULL)      t->root = n;
150	    else if (cmp < 0)        parent->left = n;
151	    else                     parent->right = n;
152	
153	    insert_fixup(t, n);
154	    t->size++;
155	    return 0;
156	}
157	
158	static struct rb_node *find_node(const rbtree_t *t, const char *key) {
159	    struct rb_node *cur = t->root;
160	    while (cur != NULL) {
161	        int cmp = strcmp(key, cur->key);
162	        if (cmp == 0) return cur;
163	        cur = (cmp < 0) ? cur->left : cur->right;
164	    }
165	    return NULL;
166	}
167	
168	static struct rb_node *tree_min(struct rb_node *n) {
169	    while (n->left != NULL) n = n->left;
170	    return n;
171	}
172	
173	/* Puts v in u's slot (u->parent, or t->root) -- the only place delete
174	 * touches t->root or reparents a node, mirroring the rotations. */
175	static void transplant(rbtree_t *t, struct rb_node *u, struct rb_node *v) {
176	    if (v != NULL) v->parent = u->parent;
177	    if (u->parent == NULL)         t->root = v;
178	    else if (u == u->parent->left) u->parent->left = v;
179	    else                            u->parent->right = v;
180	}
181	
182	/* x may be NULL (NIL); since NULL can't carry its own parent pointer,
183	 * (parent, x) is threaded through the loop as an explicit pair instead
184	 * of ever reading x->parent -- see NOTES.md's devlog on why this tree
185	 * has no shared sentinel. */
186	static void delete_fixup(rbtree_t *t, struct rb_node *parent, struct rb_node *x) {
187	    while (parent != NULL && is_black(x)) {
188	        if (x == parent->left) {
189	            struct rb_node *sib = parent->right;
190	            if (is_red(sib)) {                     /* Case 5: sibling red */
191	                sib->color = BLACK;
192	                parent->color = RED;
193	                rotate_left(t, parent);
194	                sib = parent->right;
195	            }
196	            if (is_black(sib->left) && is_black(sib->right)) { /* Case 3: both nephews black */
197	                sib->color = RED;
198	                x = parent;
199	                parent = x->parent;
200	            } else {
201	                if (is_black(sib->right)) {         /* near red / far black: convert first */
202	                    if (sib->left != NULL) sib->left->color = BLACK;
203	                    sib->color = RED;
204	                    rotate_right(t, sib);
205	                    sib = parent->right;
206	                }
207	                sib->color = parent->color;         /* Case 4: far nephew red, terminal */
208	                parent->color = BLACK;
209	                if (sib->right != NULL) sib->right->color = BLACK;
210	                rotate_left(t, parent);
211	                return;
212	            }
213	        } else {
214	            /* exact mirror: left/right swapped, rotate_right/rotate_left swapped */
215	            struct rb_node *sib = parent->left;
216	            if (is_red(sib)) {
217	                sib->color = BLACK;
218	                parent->color = RED;
219	                rotate_right(t, parent);
220	                sib = parent->left;
221	            }
222	            if (is_black(sib->left) && is_black(sib->right)) {
223	                sib->color = RED;
224	                x = parent;
225	                parent = x->parent;
226	            } else {
227	                if (is_black(sib->left)) {
228	                    if (sib->right != NULL) sib->right->color = BLACK;
229	                    sib->color = RED;
230	                    rotate_left(t, sib);
231	                    sib = parent->left;
232	                }
233	                sib->color = parent->color;
234	                parent->color = BLACK;
235	                if (sib->left != NULL) sib->left->color = BLACK;
236	                rotate_right(t, parent);
237	                return;
238	            }
239	        }
240	    }
241	    if (x != NULL) x->color = BLACK;
242	}
243	
244	int rb_delete(rbtree_t *t, const char *key) {
245	    struct rb_node *z = find_node(t, key);
246	    if (z == NULL) return -1;
247	
248	    struct rb_node *n;
249	    bool free_own_payload = true;
250	
251	    if (z->left != NULL && z->right != NULL) {
252	        struct rb_node *y = tree_min(z->right);
253	        rb_free(z->key);
254	        if (t->value_free) t->value_free(z->value);
255	        z->key = y->key;
256	        z->value = y->value;
257	        n = y;
258	        free_own_payload = false;
259	    } else {
260	        n = z;
261	    }
262	
263	    struct rb_node *child = (n->left != NULL) ? n->left : n->right;
264	    bool n_was_black = is_black(n);
265	    transplant(t, n, child);
266	
267	    if (n_was_black) {
268	        if (child != NULL) {
269	            child->color = BLACK;             /* STEP1: absorbs the debt locally */
270	        } else {
271	            delete_fixup(t, n->parent, NULL); /* STEP2: only after transplant has run */
272	        }
273	    }
274	
275	    if (free_own_payload) {
276	        rb_free(n->key);
277	        if (t->value_free) t->value_free(n->value);
278	    }
279	    rb_free(n);
280	    t->size--;
281	    return 0;
282	}
283	
284	size_t rb_size(const rbtree_t *t) {
285	    return t->size;
286	}
287	
288	static void foreach_inorder(const struct rb_node *n,
289	                             void (*fn)(const char *, void *, void *), void *ctx) {
290	    if (n == NULL) return;
291	    foreach_inorder(n->left, fn, ctx);
292	    fn(n->key, n->value, ctx);
293	    foreach_inorder(n->right, fn, ctx);
294	}
295	
296	void rb_foreach(const rbtree_t *t,
297	                void (*fn)(const char *key, void *value, void *ctx), void *ctx) {
298	    foreach_inorder(t->root, fn, ctx);
299	}
300	
301	struct validate_state {
302	    const char *prev_key;
303	    bool        order_ok;
304	    size_t      count;
305	};
306	
307	static void validate_walk(const struct rb_node *n, struct validate_state *st) {
308	    if (n == NULL) return;
309	    validate_walk(n->left, st);
310	    if (st->prev_key != NULL && strcmp(st->prev_key, n->key) >= 0) {
311	        st->order_ok = false;
312	    }
313	    st->prev_key = n->key;
314	    st->count++;
315	    validate_walk(n->right, st);
316	}
317	
318	static bool has_red_red(const struct rb_node *n) {
319	    if (n == NULL) return false;
320	    if (is_red(n) && (is_red(n->left) || is_red(n->right))) return true;
321	    return has_red_red(n->left) || has_red_red(n->right);
322	}
323	
324	/* Returns the subtree's black-height, or -1 if any root-to-NIL path within it
325	 * has already been found to disagree with another. NULL (NIL) contributes a
326	 * black-height of 1 by convention; a black node adds 1 on top of its children's
327	 * (equal) black-height. */
328	static int black_height(const struct rb_node *n) {
329	    if (n == NULL) return 1;
330	    int lh = black_height(n->left);
331	    if (lh == -1) return -1;
332	    int rh = black_height(n->right);
333	    if (rh == -1) return -1;
334	    if (lh != rh) return -1;
335	    return lh + (is_black(n) ? 1 : 0);
336	}
337	
338	int rb_validate(const rbtree_t *t) {
339	    if (is_red(t->root)) {
340	        fprintf(stderr, "rb_validate: invariant 1 violated (root is red)\n");
341	        return 1;
342	    }
343	    if (has_red_red(t->root)) {
344	        fprintf(stderr, "rb_validate: invariant 2 violated "
345	                         "(a red node has a red child)\n");
346	        return 2;
347	    }
348	    if (black_height(t->root) == -1) {
349	        fprintf(stderr, "rb_validate: invariant 3 violated "
350	                         "(root-to-NIL paths have differing black-height)\n");
351	        return 3;
352	    }
353	
354	    struct validate_state st = { .prev_key = NULL, .order_ok = true, .count = 0 };
355	    validate_walk(t->root, &st);
356	
357	    if (!st.order_ok) {
358	        fprintf(stderr, "rb_validate: invariant 4 violated "
359	                         "(in-order keys not strictly increasing under strcmp)\n");
360	        return 4;
361	    }
362	    if (st.count != t->size) {
363	        fprintf(stderr, "rb_validate: invariant 5 violated "
364	                         "(rb_size=%zu, actual node count=%zu)\n", t->size, st.count);
365	        return 5;
366	    }
367	    return 0;
368	}
369	
370	void rb_destroy(rbtree_t *t) {
371	    if (t == NULL) return;
372	    struct rb_node *cur = t->root;
373	    while (cur != NULL) {
374	        struct rb_node *next;
375	        if (cur->left == NULL) {
376	            next = cur->right;
377	            rb_free(cur->key);
378	            if (t->value_free) t->value_free(cur->value);
379	            rb_free(cur);
380	        } else {
381	            struct rb_node *left = cur->left;
382	            cur->left = left->right;
383	            left->right = cur;
384	            next = left; /* re-enter the loop rooted at the promoted node */
385	        }
386	        cur = next;
387	    }
388	    rb_free(t);
389	}
390	
391	#ifdef RBTREE_TEST_HOOKS
392	/* Test-only hooks for exercising rb_validate's negative paths (invariants
393	 * 1-5). Compiled in only when RBTREE_TEST_HOOKS is defined (test_rbtree's
394	 * build only, per the Makefile) so production/grading builds that compile
395	 * this file without the macro never see these symbols at all. Each hook
396	 * mutates only existing struct fields on nodes the tree already owns --
397	 * no allocation, no freeing -- so rb_destroy's pointer-only teardown walk
398	 * (left/right only; it never reads color, key contents, or t->size) stays
399	 * safe to call afterward regardless of which invariant was broken.
400	 *
401	 * rb_validate checks invariants in order (1: root black, 2: no red-red,
402	 * 3: black-height, 4: ordering, 5: size) and returns on the first failure,
403	 * which is what lets each hook below isolate its target invariant's return
404	 * code even when a mutation has a side effect on a later check. */
405	
406	/* Invariant 1: flip the root red. Root-color is checked first and
407	 * unconditionally, so this isolates invariant 1 regardless of anything
408	 * else about the tree. */
409	void rb_test_force_root_red(rbtree_t *t) {
410	    if (t != NULL && t->root != NULL) t->root->color = RED;
411	}
412	
413	/* Invariant 2: find a RED node with a real (non-NULL) BLACK child and flip
414	 * that child RED, producing a red-red pair. Returns 1 if found and
415	 * corrupted, 0 if the fixture didn't have the needed shape. */
416	static struct rb_node *find_red_with_black_child(struct rb_node *n) {
417	    if (n == NULL) return NULL;
418	    if (n->color == RED &&
419	        ((n->left != NULL && n->left->color == BLACK) ||
420	         (n->right != NULL && n->right->color == BLACK))) {
421	        return n;
422	    }
423	    struct rb_node *found = find_red_with_black_child(n->left);
424	    if (found != NULL) return found;
425	    return find_red_with_black_child(n->right);
426	}
427	
428	int rb_test_force_red_red(rbtree_t *t) {
429	    if (t == NULL) return 0;
430	    struct rb_node *p = find_red_with_black_child(t->root);
431	    if (p == NULL) return 0;
432	    struct rb_node *child = (p->left != NULL && p->left->color == BLACK)
433	                             ? p->left : p->right;
434	    child->color = RED;
435	    return 1;
436	}
437	
438	/* Invariant 3: find a non-root BLACK node whose parent is BLACK and whose
439	 * own children are both BLACK-or-NIL, then flip it RED. That perturbs only
440	 * that node's subtree's black count -- it can't create a red-red pair
441	 * (parent stays black, its own children stay black) and it doesn't touch
442	 * the root, so it isolates invariant 3 rather than tripping 1 or 2 first.
443	 * Returns 1 if found and corrupted, 0 otherwise. */
444	static struct rb_node *find_isolated_black_flip_target(struct rb_node *n) {
445	    if (n == NULL) return NULL;
446	    if (n->parent != NULL && n->color == BLACK && is_black(n->parent) &&
447	        is_black(n->left) && is_black(n->right)) {
448	        return n;
449	    }
450	    struct rb_node *found = find_isolated_black_flip_target(n->left);
451	    if (found != NULL) return found;
452	    return find_isolated_black_flip_target(n->right);
453	}
454	
455	int rb_test_break_black_height(rbtree_t *t) {
456	    if (t == NULL) return 0;
457	    struct rb_node *n = find_isolated_black_flip_target(t->root);
458	    if (n == NULL) return 0;
459	    n->color = RED;
460	    return 1;
461	}
462	
463	/* Invariant 4: swap the key pointers of two existing nodes (located by
464	 * their current key values), which breaks in-order strictly-increasing
465	 * order without touching allocation, color, or structure -- each string is
466	 * still owned by exactly one node afterward, just a different one. Returns
467	 * 1 if both keys were found and swapped, 0 otherwise. */
468	static struct rb_node *find_by_key(struct rb_node *n, const char *key) {
469	    while (n != NULL) {
470	        int cmp = strcmp(key, n->key);
471	        if (cmp == 0) return n;
472	        n = (cmp < 0) ? n->left : n->right;
473	    }
474	    return NULL;
475	}
476	
477	int rb_test_swap_keys(rbtree_t *t, const char *key1, const char *key2) {
478	    if (t == NULL) return 0;
479	    struct rb_node *n1 = find_by_key(t->root, key1);
480	    struct rb_node *n2 = find_by_key(t->root, key2);
481	    if (n1 == NULL || n2 == NULL || n1 == n2) return 0;
482	    char *tmp = n1->key;
483	    n1->key = n2->key;
484	    n2->key = tmp;
485	    return 1;
486	}
487	
488	/* Invariant 5: directly desync the size counter from the real node count,
489	 * touching nothing else. Works on any tree, even empty. */
490	void rb_test_bump_size(rbtree_t *t) {
491	    if (t != NULL) t->size += 1;
492	}
493	#endif
